package com.tuap.backend.persistencia;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import com.tuap.backend.auth.*; import com.tuap.backend.dominio.entidades.AuthIdentity;
public interface AuthIdentityDAO extends JpaRepository<AuthIdentity,UUID>{Optional<AuthIdentity> findByProviderAndProviderSubject(AuthProvider provider,String subject);List<AuthIdentity> findByUserIdAndRoleAndActiveTrue(UUID userId,Role role);boolean existsByUserIdAndRoleAndProviderAndActiveTrue(UUID userId,Role role,AuthProvider provider);long countByUserIdAndRoleAndActiveTrue(UUID userId,Role role);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from AuthIdentity i where i.userId=:userId and i.role=:role and i.active=true") List<AuthIdentity> lockActiveByUserIdAndRole(@Param("userId") UUID userId,@Param("role") Role role);}
